// Lightweight, dependency-free i18n. A dictionary lookup with graceful English
// fallback — so partially-translated locales (zh/ta/hi) degrade cleanly to
// English per-key instead of breaking. English + Malay are complete; the other
// three are scaffolded (core chrome) to prove the architecture scales.
// No next-intl / routing changes — the locale is a `?lang=` param (or cookie).

export const LOCALES = ["en", "ms", "zh", "zh-Hant", "ta", "hi"] as const;
export type Locale = (typeof LOCALES)[number];
export const DEFAULT_LOCALE: Locale = "en";

export const LOCALE_LABEL: Record<Locale, string> = {
  en: "English",
  ms: "Malay",
  zh: "简体中文",
  "zh-Hant": "繁體中文",
  ta: "தமிழ்",
  hi: "हिन्दी",
};

// Compact codes for the mobile header picker. Country-style codes (MY/CN/TW)
// read more clearly than the raw language codes in a tiny control; HI/TA are
// the standard ISO 639-1 codes for Hindi and Tamil. The full name in
// LOCALE_LABEL stays available for tooltips / accessibility.
export const LOCALE_SHORT: Record<Locale, string> = {
  en: "EN",
  ms: "MY",
  zh: "CN",
  "zh-Hant": "TW",
  ta: "TA",
  hi: "HI",
};

