  // Graph gallery + deck. These two pages are part of the always-on static
  // snapshot (see scripts/build-static-site.mjs) — they must never touch
  // PocketBase, so everything they render lives here or in /public.
  "gallery.title": "Graph Gallery",
  "gallery.subtitle": "Real screenshots of the live app — one graph, six views, five lenses, three personas.",
  "gallery.intro":
    "HoneyMoney isn't a ledger with charts bolted on. A household's money is modelled as a knowledge graph — income → buckets → spend → goals — and the same graph re-renders six ways, filters through any lens, and serves one person, a couple and a whole family with zero schema changes.",
  "gallery.s1.title": "Six views of the same graph",
  "gallery.s1.body": "The view switcher re-projects the identical underlying graph. Each view answers a different question.",
  "gallery.s2.title": "Any node is a lens",
  "gallery.s2.body":
    "Pick any person, income stream, bucket, vendor or category and the whole page re-renders through that lens — KPIs, graph and captions all refilter.",
  "gallery.s3.title": "One engine, three sizes of household",
  "gallery.s3.body": "Individual → couple → family. The same graph model, the same three buckets, no schema change — one product that grows with the household instead of three that don't talk to each other.",
  "gallery.live": "Open the live graph",
  "gallery.note":
    "Captured from the running app over the seeded demo data. The graph page is fully URL-driven (mode = sankey · treemap · tree · organic · bars · flow; focus = a member, node or tier), so every view above is a shareable link.",
  "gallery.sankey.t": "Sankey — where does every ringgit go?",
  "gallery.sankey.b":
    "Income (left) splits into buckets (middle), then into real spending (red) versus what stays Saved / Unspent (green). Ribbon width ∝ RM — the money-flow story in one glance, and the exact structure Honey reasons over.",
  "gallery.treemap.t": "Treemap — what's my budget made of, and what's over?",
  "gallery.treemap.b":
    "Cell area ∝ monthly allocation; colour ∝ status (green on-track → red over budget); the solid fill rises with projected spend. Best for spotting an over-committed budget at a glance.",
  "gallery.tree.t": "Tree — trace a cost to its source",
  "gallery.tree.b":
    "The budget as a branching hierarchy: spending tier → bucket → vendor. Answers \"what sits under Groceries?\" — the lineage view.",
  "gallery.organic.t": "Organic — the raw knowledge graph",
  "gallery.organic.b":
    "The force-relaxed graph itself. Node size ∝ number of connections; amber = income, blue = buckets, green = goals, red = vendors. The \"there really is a graph under here\" proof.",
  "gallery.bars.t": "Budget — budget vs actual, directly comparable",
  "gallery.bars.b":
    "Every bucket on one shared RM scale; the dashed line is the allocation cap. Red bars are the ones bleeding.",
  "gallery.flow.t": "Flow — the classic branch view",
  "gallery.flow.b":
    "Expenses on the left, household structure (buckets · goals · obligations) in the middle, income on the right — money reads right → left.",
  "gallery.person.t": "People lens — one person's money",
  "gallery.person.b":
    "Focus on a single household member: their spend, their envelopes, their vendors — without exposing anyone else. This is also the marital-safe boundary: private wallets stay private.",
  "gallery.vendor.t": "Vendor lens — one merchant's lineage",
  "gallery.vendor.b":
    "Focus on a single vendor to see which bucket it draws from and how much — useful for \"where is this shop eating my budget?\"",
  "gallery.category.t": "Category lens — one spending tier",
  "gallery.category.b": "Focus on a category tier (here essentials / Tier 1) to isolate non-negotiables from lifestyle and savings.",
  "gallery.solo.t": "Individual — a multi-stream freelancer",
  "gallery.solo.b":
    "A household of one with five income streams — freelance design, an online shop, a rented studio, dividends and content — flowing into living costs, reserves and investments. Proof the model handles gig and irregular-income realities.",
  "gallery.soloLens.t": "Income lens on the freelancer",
  "gallery.soloLens.b": "Isolate a single revenue stream to see exactly what it funds.",
  "gallery.couple.t": "Couple — two incomes, one set of obligations",
  "gallery.couple.b":
    "Both salaries fan into the same shared must-paid buckets, and each partner funds a personal bucket of their own. Funding transparency where it helps, spending autonomy where it doesn't — the split that keeps money out of the argument.",
  "gallery.coupleLens.t": "People lens on the couple",
  "gallery.coupleLens.b":
    "Focus one partner to see what they fund and what they spend. The other partner's personal bucket keeps its total and loses its line items — privacy enforced by the graph, not by a promise.",

  "deck.title": "Deck & Documents",
  "deck.subtitle": "The pitch, the one-page summary, the AI disclosure and the demo — all in one place.",
  "deck.pitch.t": "Pitch deck",
  "deck.pitch.b": "The full deck: problem, product, market, model, traction and the ask.",
  "deck.summary.t": "One-page project summary",
  "deck.summary.b": "The whole project on a single page — for a reader with two minutes.",
  "deck.ai.t": "AI disclosure",
  "deck.ai.b": "Exactly which models we use, for what, and what we never send them.",
  "deck.demo.t": "Demo video",
  "deck.demo.b": "Under three minutes: capture → parse → bucket → insight → dashboard, in the live app.",
  "deck.pdf": "Open PDF",
  "deck.watch": "Watch",
  "deck.note": "Prepared for the MAIC Nexus Challenge 2026 (Track T3). Figures are illustrative; nothing here is financial advice.",

  // ── H-Score ────────────────────────────────────────────────────────────────
  "hscore.title": "Money health",
  "hscore.provisional": "Provisional",
  "hscore.provisional.why": "We show a provisional score until there's enough to be honest about. Still needed:",
  "hscore.missing.income": "declare your monthly income",
  "hscore.missing.transactions": "log at least {n} entries in the last 30 days (you have {have})",
  "hscore.missing.buckets": "put at least one entry in every bucket",
  "hscore.window": "Rolling 90 days. Annual items (road tax, insurance, school fees, Raya) are spread across 12 months, so one big legitimate payment doesn't crater the month.",
  "hscore.band.building": "Building",
  "hscore.band.steady": "Steady",
  "hscore.band.strong": "Strong",
  "hscore.band.thriving": "Thriving",
  "hscore.band.building.sub": "The foundations, one month at a time.",
  "hscore.band.steady.sub": "Covering the essentials and putting something away.",
