  "guide.title": "HoneyMoney — 指南",
  "guide.subtitle": "拨款透明，支出自主 — 一个金钱引擎，兼顾个人、家庭与生意。",
  "guide.howto.title": "如何使用",
  "guide.howto.1.label": "选择一个身份",
  "guide.howto.1.body": "顶部的切换器",
  "guide.howto.1.body2": "可在家庭、生意或单人之间切换。同一引擎，不同标签。",
  "guide.howto.2.label": "把钱当作一幅图来看",
  "guide.howto.2.body": "对同一数据的六种视图：",
  "guide.howto.2.sankeyDesc": "每一分钱的流向",
  "guide.howto.2.treemapDesc": "预算所在之处",
  "guide.howto.2.networkLabel": "网络",
  "guide.howto.2.barsLabel": "柱状",
  "guide.howto.2.and": "和",
  "guide.howto.3.label": "聚焦一个视角",
  "guide.howto.3.body": "按收入来源、预算篮/支出、类别，或某位",
  "guide.howto.3.person": "成员",
  "guide.howto.3.body2": "（仅其支出）来切分一切。一键即可清除。",
  "guide.howto.4.label": "添加任何内容",
  "guide.howto.4.addPanel": "添加到图表",
  "guide.howto.4.body": "面板可添加一笔支出、一个收入来源、一个预算篮/部门或一笔分配。对于支出，你可以",
  "guide.howto.4.type": "打字输入，或",
  "guide.howto.4.scan": "扫描收据",
  "guide.howto.4.body2": "两者都在你的设备上运行，免费，且不消耗 AI 额度。",
  "guide.howto.5.label": "三个预算篮",
  "guide.howto.5.body": "金钱分为",
  "guide.howto.5.needs": "必付",
  "guide.howto.5.savings": "储蓄",
  "guide.howto.5.shield": "（你的未来防护罩），以及",
  "guide.howto.5.personal": "日常开销",
  "guide.howto.5.body2": "— 日常开销篮",
  "guide.howto.5.notItemized": "不逐项记录",
  "guide.howto.5.body3": "，这是刻意的设计。",
  "guide.keep.title": "保存你的记录",
  "guide.keep.intro": "记账数据很小——每条约 400 字节，一天记三条，一年也不到半 MB。真正增长的是照片：一张收据图约 250 KB，若每五条记录附一张，一年约 55 MB，是记录本身的一百多倍。",
  "guide.keep.1.label": "永远不要删除记录。",
  "guide.keep.1.body": "它的价值就在于时间跨度。H-Score、趋势和目标都要读多年的历史，删掉的一年就是它们看不见的一年。按一天三条计算，约需 45 年才会达到全部记录无法一次载入的程度。",
  "guide.keep.2.label": "要管理的是照片。",
  "guide.keep.2.body": "记录没有图片也完全成立。大约第三年起——或当你的副本超过约 50 MB 时——取下不再需要的照片，保留全部记录。",
  "guide.keep.3.label": "每年下载一份副本。",
  "guide.keep.3.body": "打开「你的副本」并按保存。这是为了安全而非空间：即使我们不在了，它仍在。取下照片前请先这样做。",
  "guide.keep.4.label": "若申报税务减免，请保存七年。",
  "guide.keep.4.body": "LHDN 要求证明文件保存七年，若你申报减免或有营业收入，请保留该期限。其他情况保存两年足以应付保修与争议。此为一般资讯，非税务建议。",
  "guide.privacy.title": "你的隐私",
  "guide.privacy.1.label": "默认隐私优先。",
  "guide.privacy.1.body": "演示运行在运营者机器上的本地数据库中 — 你的家庭数据无需离开该机器。",
  "guide.privacy.2.label": "截图只读取，不留存。",
  "guide.privacy.2.body": "解析收据时，我们只存储结构化字段（商家、金额、日期）—",
  "guide.privacy.2.not": "而非",
  "guide.privacy.2.body2": "原始图像。",
  "guide.privacy.3.label": "设备端采集不发送任何内容。",
  "guide.privacy.3.body": "收据扫描在你的浏览器中运行 — 读取时不会向任何地方发送。若你将照片附加到记录，它会与该记录一起保存；你可以随时删除。",
  "guide.privacy.4.label": "个人钱包保持私密。",
  "guide.privacy.4.body": "第三篮的支出不逐项记录 — 自主，而非监控。",
  "guide.privacy.5.label": "数据由你掌控。",
  "guide.privacy.5.body": "随时可添加或移除成员；移除某人会保留其过往支出，但取消其归属。没有广告。我们不出售你的数据。",
  "guide.privacy.6.label": "可选 AI 极简。",
  "guide.privacy.6.body": "若启用 AI 洞察，它只接收你预算状态的简短摘要 — 绝不涉及你的原始交易或身份。",
  "guide.disclaimer.title": "免责声明",
  "guide.disclaimer.1.label": "非财务建议。",
  "guide.disclaimer.1.body": "HoneyMoney 是一款信息性的预算与洞察工具，而非持牌财务顾问。如需个人建议，请咨询持牌理财规划师，或在马来西亚咨询",
  "guide.disclaimer.1.body2": "（免费信用辅导）。",
  "guide.disclaimer.2.label": "非银行。",
  "guide.disclaimer.2.body": "HoneyMoney 不持有、转移或投资你的资金。它只帮助你查看和规划。文中提及的任何储蓄/投资产品均属于其持牌提供商。",
  "guide.disclaimer.3.label": "数字为估算。",
  "guide.disclaimer.3.body": "预测基于你输入的内容外推；它们是规划辅助工具，而非保证。请务必与你的银行/电子钱包对账单核对。",
  "guide.disclaimer.4.label": "演示数据为虚构。",
  "guide.disclaimer.4.body": "Rahman 一家、那家咖啡馆以及 Aisha 均为示意 — 如与真实人物或企业雷同，纯属巧合。",
  "guide.disclaimer.5.label": "合规由你负责。",
  "guide.disclaimer.5.body": "对于商业用途（税务、EPF/SOCSO/EIS、SST、LHDN 电子发票），HoneyMoney 只是一个现金流视角 — 请通过你的会计师或核准软件提交法定申报。",
  "guide.contact": "有疑问或数据请求？请联系设置此实例的家庭/生意运营者。另请参阅项目中的 AI 使用披露，见",
  "g.caption.sankey": "每一分钱，皆可追溯：收入分流进各预算篮，再流向实际支出（红色）与留存的储蓄（绿色）。带宽 ∝ RM。",
  "g.caption.treemap": "预算构成一目了然：格子面积 ∝ 月度分配，颜色 ∝ 状态，实心填充随预计支出上升。",
  "g.caption.tree": "家庭预算呈分支结构 — 支出层级 → 预算篮 → 商家。悬停节点可追溯其脉络。",
  "g.caption.organic": "原始知识图谱，经力导向松弛布局。节点大小 ∝ 连接数；悬停可聚焦某节点及其邻居。",
  "g.caption.bars": "预算与实际置于同一 RM 刻度上，因此每个预算篮都可直接比较。虚线 = 分配上限。",
  "g.caption.flow": "经典分支视图 — 支出在左，家庭结构居中，收入在右。",
