  "home.ctaRepo": "repo-ஐப் பார்",
  "home.card1.title": "3-பக்கெட் மாதிரி",
  "home.card1.body": "பேரம் பேச முடியாத கட்டாயச் செலவுகள், தானாகவே % ஒதுக்கும் சேமிப்பு, மற்றும் கண்காணிப்பு நிற்கும் செலவுகள் — கண்காணிப்பைவிட சுயாட்சி.",
  "home.card2.title": "பூஜ்ஜிய-ஒருங்கிணைப்பு பதிவு",
  "home.card2.body": "ஒரு TNG/MAE/GrabPay ஸ்கிரீன்ஷாட்டை Telegram-க்கு அனுப்பவும்; Gemini விற்பனையாளர், தொகை மற்றும் நேரத்தை தானாகவே படிக்கிறது.",
  "home.card3.title": "அறிவு வரைபடம்",
  "home.card3.body": "பணம் PocketBase-இல் முனைகள் + விளிம்புகளாக மாதிரியாக்கப்படுகிறது, எனவே செலவின் வேகம் ஒரு இலக்கை அச்சுறுத்தும்போது Honey உங்களை எச்சரிக்கிறது.",
  "home.outcome": "படம் எடுங்கள், அல்லது தட்டச்சு செய்யுங்கள். பணம் உண்மையில் எங்கே போகிறது என்பதைப் பாருங்கள்.",
  "try.kicker": "இங்கேயே முயற்சி செய்யுங்கள்",
  "try.noSignup": "பதிவு தேவையில்லை · எதுவும் பதிவேற்றப்படவில்லை",
  "try.inputLabel": "ஒரு செலவை விவரியுங்கள் — எடுத்துக்காட்டாக, kopi 6.50",
  "try.placeholder": "kopi 6.50",
  "try.tryOne": "அல்லது ஒன்றைத் தட்டவும்:",
  "try.eg1": "kopi 6.50",
  "try.eg2": "Grab 18.40",
  "try.eg3": "TNB கட்டணம் 142",
  "try.unknownVendor": "பெயரிடப்படாத செலவு",
  "try.checkThis": "சரிபார்க்கத் தகுந்தது",
  "try.honey.must_paid": "கட்டாயச் செலவுப் பக்கெட் பேரம் பேச முடியாதவற்றை வைத்திருக்கிறது. ஒரு பில் பகிரப்பட்ட இலக்கை அமைதியாகப் பாதிக்காமல் இருக்க Honey இதைக் கவனிக்கிறது.",
  "try.honey.savings": "சேமிப்பு செலவழிக்கப்படும் முன்பே ஒதுக்கப்படுகிறது — ஒரு இலக்கு சரியான நேரத்தில் வருமா என்பதை இந்தப் பக்கெட்டே தீர்மானிக்கிறது.",
  "try.honey.spendings": "செலவுகள் உங்களுடையது. HoneyMoney மொத்தத்தை மட்டும் பதிவு செய்து அத்துடன் நிறுத்திக்கொள்கிறது — இந்தப் பக்கெட்டை வீட்டில் வேறு யாருக்கும் விவரமாகக் காட்டுவதில்லை.",
  "try.honey.income": "வருமானம் எந்த பக்கெட்டிலும் இராது — அது வெளியிலிருந்து வருகிறது, உங்கள் ஒதுக்கீடுகள் அது எங்கு செல்கிறது என்பதை முடிவு செய்கின்றன.",
  "try.honey.income_other": "இது திரும்பி வந்த பணம், சம்பாதித்த பணம் அல்ல. வரவாகப் பதிவாகி, செலவில் சேராது — ஆனால் சம்பளமாகக் கருதப்படாது.",
  "try.honey.expense_other": "செலவாகப் பதிவு, எதற்கு என்று ஊகிக்காமல். எப்போது வேண்டுமானாலும் ஒரு பக்கெட்டுக்கு மாற்றலாம்.",
  "try.eg4": "சம்பளம் 5000",
