  "hscore.window": "நகரும் 90 நாட்கள். ஆண்டுச் செலவுகள் (சாலை வரி, காப்பீடு, பள்ளிக் கட்டணம், ஹரி ராயா) 12 மாதங்களாகப் பரவலாக்கப்படுகின்றன, எனவே ஒரு பெரிய நியாயமான கட்டணம் அந்த மாதத்தைச் சரிக்காது.",
