  "hscore.thriving.title": "செழிப்பானது",
  "hscore.thriving.body": "சேமிப்பு, சுமை, கடன், இருப்பு அனைத்தும் நல்ல நிலையில். இந்த நிலையில் ஒரு மோசமான மாதம் ஒரு சிரமமே, நெருக்கடி அல்ல.",
  "hscore.goals.title": "இலக்குகள்",
  "hscore.goals.hint": "எளிய மொழியில், உங்கள் பலவீனமான கூறிலிருந்து பெறப்பட்டது. அதைச் சரிசெய்யும் தயாரிப்பு வகைகளைக் காண ஒன்றைத் தட்டவும்.",
  "hscore.goal.savingsRate": "ஒவ்வொரு மாதமும் அதிகம் ஒதுக்குங்கள்",
  "hscore.goal.essentialBurden": "மாதம் கட்டாயம் செலுத்த வேண்டியதைக் குறையுங்கள்",
  "hscore.goal.debtService": "கடன் திருப்பிச் செலுத்தலுக்குப் போவதைக் குறையுங்கள்",
  "hscore.goal.emergencyBuffer": "3 மாத அவசரகால இருப்பை உருவாக்குங்கள்",
  "hscore.goal.personalCap": "உங்கள் சொந்தத் தனிப்பட்ட செலவு வரம்பிற்குள் இருங்கள்",
  "hscore.goal.savingsRate.low": "ஒவ்வொரு மாதமும் ஏதாவது சேமிக்கத் தொடங்குங்கள் — தொகையை விடத் தொடர்ச்சியே முக்கியம்",
  "hscore.goal.savingsRate.mid": "சேமிக்கும் பங்கை ஒரு சதவீதம் இரண்டு உயர்த்துங்கள்",
  "hscore.goal.savingsRate.high": "வருமானம் மாறும்போது இப்போதுள்ள சேமிப்பு விகிதத்தைக் காத்துக்கொள்ளுங்கள்",
  "hscore.goal.essentialBurden.low": "கட்டாயச் செலவு வருமானத்தின் பெரும்பகுதியை எடுக்கிறது — மிகப் பெரிய ஒன்றிரண்டில் தொடங்குங்கள்",
  "hscore.goal.essentialBurden.mid": "ஒரு தொடர் அத்தியாவசியத்தைக் குறைத்து மாதத்தைத் தளர்த்துங்கள்",
  "hscore.goal.essentialBurden.high": "அத்தியாவசியங்கள் நன்கு கட்டுக்குள் — புதிய கடமைகளைக் கட்டாயச் செலவில் சேர்க்க வேண்டாம்",
  "hscore.goal.debtService.low": "திருப்பிச் செலுத்தல் கனமானது — எந்தக் கடன் விரைவில் முடியும் எனக் கண்டறியுங்கள்",
  "hscore.goal.debtService.mid": "மற்றவை குறைந்து கொண்டிருக்கும்போது விலையுயர்ந்த கடனைத் தாக்குங்கள்",
  "hscore.goal.debtService.high": "கடன் இலகுவானது — இப்போதைய முக்கிய அபாயம் புதிய தவணையைச் சேர்ப்பதே",
  "hscore.goal.emergencyBuffer.low": "இருப்பைத் தொடங்குங்கள் — இரண்டு வாரம் கூட மோசமான மாதத்தின் விலையை மாற்றும்",
  "hscore.goal.emergencyBuffer.mid": "இருப்பை மூன்று மாதக் கட்டாயச் செலவை நோக்கி வளர்க்கவும்",
  "hscore.goal.emergencyBuffer.high": "செலவுகள் உயரும்போது இருப்பையும் நிரப்புங்கள்",
  "hscore.goal.personalCap.low": "தனிப்பட்ட செலவு வரம்பைத் தாண்டிவிட்டது — வரம்பு தவறா, செலவு தவறா எனப் பாருங்கள்",
  "hscore.goal.personalCap.mid": "பெரும்பாலான மாதங்களில் தனிப்பட்ட வரம்புக்கு அருகில் முடிக்கிறீர்கள்",
  "hscore.goal.personalCap.high": "தனிப்பட்ட வரம்புக்குள் வசதியாக",
