  "dash.bucketsEmpty.title": "இன்னும் பிரிவுகள் அமைக்கப்படவில்லை",
  "dash.bucketsEmpty.body": "வருமானமும் ஒதுக்கீடுகளும் சேர்க்கப்பட்டதும் பிரிவுகள் தோன்றும். வரைபடத்தைத் திறந்து ஒரு வருமான மூலத்தைச் சேர்த்து, அதை உங்கள் மூன்று பிரிவுகளாகப் பிரியுங்கள்.",
  "dash.bucketsEmpty.cta": "வரைபடத்தை அமைக்க",
  "dash.recentEmptyCta": "உங்கள் முதல் செலவைச் சேர்க்கவும்",
  "dash.down.title": "உங்கள் பதிவுகளை இப்போது எங்களால் அணுக முடியவில்லை",
  "dash.down.body": "இது எங்கள் பக்கத்துப் பிரச்சினை, உங்களுடையது அல்ல — உங்கள் குடும்பப் பதிவுகளை வைத்திருக்கும் சேவையகம் பதிலளிக்கவில்லை. வழக்கமாகச் சில நிமிடங்களில் திரும்பும்.",
  "dash.down.bodyWhere": "இது எங்கள் பக்கத்துப் பிரச்சினை, உங்களுடையது அல்ல — {where} ஐ வைத்திருக்கும் சேவையகம் பதிலளிக்கவில்லை. வழக்கமாகச் சில நிமிடங்களில் திரும்பும்.",
  "dash.down.safe": "எதுவும் இழக்கப்படவில்லை. உங்கள் பதிவுகள் பாதுகாப்பாக உள்ளன, இணையமின்றிச் சேர்ப்பவை நாங்கள் திரும்பியதும் ஒத்திசைக்கப்படும்.",
