  "guide.howto.title": "इसे कैसे इस्तेमाल करें",
  "guide.howto.1.label": "एक व्यक्ति चुनें",
  "guide.howto.1.body": "सबसे ऊपर का स्विचर",
  "guide.howto.1.body2": "एक परिवार, एक बिज़नेस, या अकेले व्यक्ति के बीच बदलता है। वही इंजन, अलग लेबल।",
  "guide.howto.2.label": "पैसे को तस्वीर की तरह पढ़ें",
  "guide.howto.2.body": "एक ही डेटा पर छह दृश्य:",
  "guide.howto.2.sankeyDesc": "हर रिंगिट का प्रवाह",
