  "guide.howto.3.label": "एक लेंस पर फोकस करें",
  "guide.howto.3.body": "सब कुछ किसी आय स्रोत, बकेट/खर्च, श्रेणी, या किसी",
  "guide.howto.3.person": "व्यक्ति",
  "guide.howto.3.body2": "(केवल उनका खर्च) के हिसाब से बाँटें। हटाने के लिए एक क्लिक।",
  "guide.howto.4.label": "कुछ भी जोड़ें",
  "guide.howto.4.addPanel": "ग्राफ़ में जोड़ें",
  "guide.howto.4.body": "पैनल एक खर्च, आय स्रोत, बकेट/विभाग, या आवंटन जोड़ता है। खर्च के लिए आप",
  "guide.howto.4.type": "इसे टाइप करें, या",
  "guide.howto.4.scan": "रसीद स्कैन करें",
  "guide.howto.4.body2": "दोनों आपके डिवाइस पर, मुफ़्त, बिना किसी AI टोकन के चलते हैं।",
  "guide.howto.5.label": "3 बकेट",
