  "hscore.goal.essentialBurden.high": "ज़रूरी खर्च अच्छी तरह नियंत्रित हैं — नई ज़िम्मेदारियाँ अनिवार्य में न आने दें",
  "hscore.goal.debtService.low": "किस्तें भारी हैं — पता करें कौन-सा ऋण सबसे पहले खत्म होगा",
  "hscore.goal.debtService.mid": "बाकी घटते रहें, तब तक सबसे महँगे ऋण पर ध्यान दें",
  "hscore.goal.debtService.high": "कर्ज़ हल्का है — अभी मुख्य जोखिम एक नई किस्त जोड़ना है",
  "hscore.goal.emergencyBuffer.low": "कोष बनाना शुरू करें — दो हफ़्ते भी बुरे महीने की कीमत बदल देते हैं",
