  "hscore.goal.personalCap.low": "निजी खर्च सीमा पार कर चुका है — देखें कि गलत क्या है, सीमा या खर्च",
  "hscore.goal.personalCap.mid": "ज़्यादातर महीने आप अपनी निजी सीमा के करीब खत्म करते हैं",
