  "setup.stack.title": "AI इंजन",
  "setup.stack.body": "HoneyMoney एक मुफ़्त, बहु-प्रदाता AI स्टैक पर चलता है — एक सेटिंग से इंजन बदलें, कोई बंधन नहीं:",
