  "setup.remove.title": "ऐप इंस्टॉल और हटाना",
  "setup.remove.body": "इंस्टॉल करने पर HoneyMoney आपकी होम स्क्रीन पर आ जाता है — कोई ऐप स्टोर नहीं (मेन्यू → ऐप इंस्टॉल करें, या बैनर से)। हटाने के लिए किसी भी ऐप की तरह अनइंस्टॉल करें: Android पर आइकॉन दबाए रखें → अनइंस्टॉल। ऐप हटाने से आपका खाता नहीं मिटता —",
