  "setup.disclaimer": "AI रसीदें सिर्फ़ इसलिए पढ़ता है कि आपको टाइप न करना पड़े — सब कुछ संपादित या पूर्ववत किया जा सकता है। निजता का वादा और अस्वीकरण गाइड में देखें।",
  "setup.ai.title": "AI इंजन — Ask Honey को चलाएँ",
  "setup.ai.body": "Ask Honey आपके अपने आँकड़ों पर सवालों के जवाब देता है — “क्या हम यह वहन कर सकते हैं?”, “बचत कैसी चल रही है?” — उसी परिवार का उपयोग करते हुए जिसमें आप लॉग-इन हैं। इसके लिए एक AI इंजन चालू होना चाहिए। नीचे तीनों की मुफ़्त सीमा है, और Ollama पूरी तरह आपकी मशीन पर चलता है।",
