  "setup.ai.howTo": "कैसे चालू करें",
  "setup.ai.askHint": "जैसे ही कोई इंजन जवाब देता है, Ask Honey आपके डैशबोर्ड पर दिखने लगता है। यह आँकड़े नहीं गढ़ता: इसका कहा हर नंबर उसी फ़ंक्शन से निकलता है जो आपका H-Score बनाता है, और जिस जवाब में कोई अनजाना नंबर हो उसे हटाकर सादा जवाब दिया जाता है।",
