  "more.privacy": "श्रेणी-सीमाएँ, लक्ष्य और निर्यात यहाँ रहते हैं ताकि रोज़ के तीन टैब साफ़-सुथरे रहें। डेमो सार्वजनिक है और उसमें आपका कोई डेटा नहीं।",
