  "cap.way.sampleNote": "डेमो में ये एक नमूना खोलते हैं ताकि आप समीक्षा वाला चरण देख सकें; असली ऐप आपका कैमरा इस्तेमाल करता है।",
  "cap.neverAuto": "कुछ भी सीधे आपकी बही में नहीं लिखा जाता। हर बार दर्ज की गई चीज़ पहले एक ड्राफ़्ट बनती है जिसे आप जाँचकर पक्का करते हैं — पार्सर सुझाव देता है, पक्का आप करते हैं।",
