  "home.path.kicker": "पहली बार",
  "home.path.title": "अजनबी से आपकी पहली अंतर्दृष्टि तक, तीन मिनट",
  "home.path.s1.title": "बिना लॉग-इन आज़माएँ",
  "home.path.s1.body": "ऊपर वाला बॉक्स असली पार्सर चलाता है — वही जो ऐप इस्तेमाल करता है। न खाता, न अपलोड; अपना नेटवर्क टैब देख लीजिए।",
  "home.path.s2.title": "साइन अप करें",
  "home.path.s2.body": "ईमेल और पासवर्ड, बस इतना। तीनों श्रेणियाँ परिवार के साथ ही बन जाती हैं, इसलिए आपको कभी खाली सूची नहीं मिलेगी।",
  "home.path.s3.title": "आपका पहला खर्च",
  "home.path.s3.body": "तस्वीर लें या टाइप करें। AI सुझाव देता है और आप पक्का करते हैं — और हर सहेजना वापस लिया जा सकता है।",
  "home.path.s4.title": "Honey उसे पढ़कर सुनाता है",
  "home.path.s4.body": "आपके अपने आँकड़े से एक अंतर्दृष्टि, फिर ग्राफ़ दिखाता है वह कहाँ गया। तैयार हों तो साथी को आमंत्रित करें।",
  "guide.install.title": "अपने फ़ोन पर इंस्टॉल करें",
  "guide.install.body": "HoneyMoney को होम स्क्रीन पर जोड़ें — ऑफ़लाइन भी चलता है, ऐप स्टोर की ज़रूरत नहीं। Android पर ☰ मेन्यू खोलें → “ऐप इंस्टॉल करें”, एक टैप में हो जाएगा। iPhone / iPad पर Apple इसे केवल Safari से करने देता है:",
  "guide.ai.title": "AI — यह क्या करता है (और क्या नहीं)",
  "guide.ai.intro": "AI वैकल्पिक है। बिना किसी कुंजी के भी यह ऐप RM 0 पर चलता है — रसीद स्कैनिंग आपके डिवाइस पर होती है। AI चालू करने पर दर्ज करना एक ऐसा सहायक बन जाता है जो आपके अपने धन-ग्राफ़ पर सोचता है, कोई सामान्य चैटबॉट नहीं: वह हमेशा सुझाव देता है, पक्का आप करते हैं, और आपकी सहमति से पहले कुछ भी सहेजा नहीं जाता।",
  "guide.ai.1.label": "आपके इतिहास के संदर्भ में रसीद पढ़ता है",
  "guide.ai.1.body": "कोई तस्वीर या ई-वॉलेट स्क्रीनशॉट भेजिए — Honey राशि, विक्रेता और तारीख़ पढ़ लेता है, उसे उसी श्रेणी में डालता है जो आप आम तौर पर उस दुकान के लिए इस्तेमाल करते हैं, संभावित दोहराव को चिह्नित करता है (“एक ही रसीद दोनों साथियों ने भेज दी” वाला जाल), और सदस्यता या आपके लिहाज़ से असामान्य राशि को पकड़ता है — मापदंड आपका अपना अतीत है, किसी अजनबी का औसत नहीं।",
  "guide.ai.2.label": "आगे की ओर देखता है, कभी डाँटता नहीं",
  "guide.ai.2.body": "Honey की अंतर्दृष्टि देखती है कि महीना किस ओर जा रहा है — जैसे “इस रफ़्तार पर आपका बचत लक्ष्य लगभग छह हफ़्ते खिसक जाएगा” — और एक पुनर्संतुलन सुझाती है जिसे आप मानें या छोड़ दें। वह योजना की बात करती है, आपके निजी खर्च की नहीं, और तीसरी श्रेणी का ब्योरा कभी नहीं देती।",
  "guide.ai.3.label": "ऑफ़लाइन चलता है, कुछ खर्च नहीं",
  "guide.ai.3.body": "रसीद स्कैनिंग आपके डिवाइस पर बिना किसी टोकन के चलती है। ग्राफ़ पर आधारित ज़्यादा समझदार पठन चाहिए, तभी एक मुफ़्त कुंजी (Groq · Gemini · Ollama) जोड़िए।",
  "guide.ai.4.label": "नियंत्रण आपके पास रहता है",
  "guide.ai.4.body": "AI सुझाव देता है; आप पक्का करते हैं या सुधारते हैं। सहेजा वही जाता है जो आपने सुधारा, और हर बदलाव एक छेड़छाड़-रोधी ऑडिट ट्रेल में दर्ज होता है।",
  "guide.ai.setupLink": "इसे सेट करें →",
  "guide.ai.note": "Honey शैक्षिक है, वित्तीय सलाह नहीं — नीचे अस्वीकरण देखें।",
  "dir.title": "उत्पाद डायरेक्टरी",
  "dir.browse.intro": "एक श्रेणी चुनें। हर प्रदाता अपना नियामक और लाइसेंस संदर्भ बताता है ताकि आप खुद जाँच सकें। यहाँ कुछ भी रैंक, स्कोर या सिफ़ारिश नहीं है।",
  "dir.back": "अपने स्कोर पर लौटें",
  "dir.intro": "इस श्रेणी के लाइसेंसधारी प्रदाता। सूचीबद्ध हैं, सिफ़ारिश नहीं — क्रम आपकी पसंद का है और वह कभी आपके स्कोर पर निर्भर नहीं करता।",
