  "gallery.title": "ग्राफ़ गैलरी",
  "gallery.subtitle": "चालू ऐप के असली स्क्रीनशॉट — एक ग्राफ़, छह नज़रिए, पाँच लेंस, तीन किरदार।",
  "gallery.s1.title": "एक ही ग्राफ़ के छह नज़रिए",
  "gallery.s1.body": "व्यू स्विचर उसी अंतर्निहित ग्राफ़ को फिर से प्रक्षेपित करता है। हर नज़रिया एक अलग सवाल का जवाब देता है।",
