  "gallery.s3.title": "एक इंजन, तीन आकार के परिवार",
  "gallery.s3.body": "व्यक्ति → युगल → परिवार। वही ग्राफ़ मॉडल, वही तीन श्रेणियाँ, कोई ढाँचा-बदलाव नहीं — एक उत्पाद जो परिवार के साथ बढ़ता है, तीन ऐसे नहीं जो आपस में बात ही न करें।",
