  "demo.title": "HoneyMoney आज़माएँ",
  "demo.subtitle": "चार मलेशियाई परिवार, हर एक के साल भर के खर्च। साइन-अप की ज़रूरत नहीं — आपके बदलाव सिर्फ़ इस सत्र के हैं और रीलोड पर मिट जाते हैं।",
