  "demo.persona.individual.name": "Suria",
  "demo.persona.individual.blurb": "एक तनख़्वाह, कोई आश्रित नहीं, माता-पिता की मदद करती हैं। अनिवार्य खर्च काबू में है और बचत की आदत सच्ची — बस कोष अब भी नहीं बना।",
  "demo.persona.couple.name": "Nadia & Faiz",
  "demo.persona.couple.blurb": "दो आय एक गृह-ऋण में, और दोनों की अपनी-अपनी निजी श्रेणी। महीना किसी तरह कट जाता है; कमी है वह कोष जो मुश्किल से एक महीने से ऊपर है।",
  "demo.persona.family.name": "Azlan परिवार",
  "demo.persona.family.blurb": "चार लोग, RM7,000 सकल पर। किराए के ऊपर एक कार, PTPTN और स्कूल फीस — यहाँ कुछ भी उनकी ग़लती नहीं, यह बस गणित का नतीजा है।",
  "demo.persona.thriving.name": "Hafiz & Lina",
  "demo.persona.thriving.blurb": "दो वरिष्ठ तनख़्वाहें, वैसे ही ऋण पर, पर आय ज़्यादा। चार महीने से ज़्यादा का कोष — बुरा महीना असुविधा है, संकट नहीं।",
