  "guide.disclaimer.title": "免責聲明",
  "guide.disclaimer.1.label": "非財務建議。",
  "guide.disclaimer.1.body": "HoneyMoney 是資訊性的預算與洞察工具，而非持牌財務顧問。如需個人建議，請諮詢持牌理財規劃師，或在馬來西亞洽詢",
  "guide.disclaimer.1.body2": "（免費信用諮詢）。",
  "guide.disclaimer.2.label": "非銀行。",
  "guide.disclaimer.2.body": "HoneyMoney 不持有、不移轉、也不投資你的資金。它只協助你檢視與規劃。所提及的任何儲蓄／投資產品，皆歸屬其各自的持牌供應商。",
  "guide.disclaimer.3.label": "數字為估計值。",
  "guide.disclaimer.3.body": "預測是由你所輸入的內容外推而來；它們是規劃輔助工具，而非保證。請務必與你的銀行／電子錢包對帳單核對。",
  "guide.disclaimer.4.label": "示範資料為虛構。",
  "guide.disclaimer.4.body": "Rahman 一家、那間咖啡館與 Aisha 皆為示意 — 如與真實人物或企業雷同，純屬巧合。",
  "guide.disclaimer.5.label": "合規責任在你。",
  "guide.disclaimer.5.body": "就商業用途而言（稅務、EPF／SOCSO／EIS、SST、LHDN 電子發票），HoneyMoney 是現金流的檢視視角 — 法定申報請透過你的會計師或核准的軟體辦理。",
  "guide.contact": "有疑問或想提出資料查詢？請聯絡設定此執行個體的家庭／商業營運者。另請參閱本專案中的 AI 使用揭露，位於",
  "g.caption.sankey": "每一塊令吉，皆被追蹤：收入分流入各帳戶籃，再流向實際支出（紅）或保留為儲蓄（綠）。緞帶寬度 ∝ RM。",
  "g.caption.treemap": "一眼掌握預算構成：格子面積 ∝ 每月分配、顏色 ∝ 狀態，而實心填滿的高度隨預估支出上升。",
  "g.caption.tree": "家庭預算呈現為分支結構 — 支出層級 → 帳戶籃 → 商家。將游標移到節點上即可追溯其脈絡。",
  "g.caption.organic": "原始知識圖譜，經力導向鬆弛佈局。節點大小 ∝ 連結數；移動游標可聚焦某個節點及其鄰居。",
  "g.caption.bars": "預算與實際落在同一個共享的 RM 尺度上，因此每個帳戶籃都能直接比較。虛線 = 分配上限。",
  "g.caption.flow": "經典的分支檢視 — 支出在左、家庭結構在中、收入在右。",
