  "ask.needsPrice.labelled": "{label} 要多少錢？給我一個價格，我就照你的計畫算一遍。我不會去猜——編出來的價格只會給你一個看起來很像樣、卻答錯了問題的答案。",
  "ask.needsPrice.bare": "那要花多少？給我一個數字，我就告訴你它會對你的應急儲備和 H-Score 造成什麼影響。我寧可問，也不猜。",
  "ask.unclear": "我不確定那要算什麼。試試「旅行 RM2,000 我們負擔得起嗎？」、「如果收入少 20% 會怎樣？」，或者「我們還能撐多久？」",
