  "home.path.title": "三分鐘，從陌生人到你的第一個洞察",
  "home.path.s1.title": "不登入，直接試",
  "home.path.s1.body": "上面那個輸入框跑的是真正的解析器——和應用程式裡用的是同一個。不用帳戶，不上傳；你可以自己查看網路請求。",
  "home.path.s2.title": "註冊",
  "home.path.s2.body": "電郵和密碼，別的都不要。三個分類會隨家庭一起建好，所以你不會面對一個空列表。",
  "home.path.s3.title": "你的第一筆開銷",
  "home.path.s3.body": "拍下來或打字輸入。AI 提議，你確認——而且每一次儲存都可以收回。",
  "home.path.s4.title": "Honey 讀給你聽",
  "home.path.s4.body": "從你自己的數字裡得出一條洞察，然後圖譜顯示它去了哪裡。準備好了，就邀請另一半加入。",
  "guide.install.title": "安裝到你的手機",
  "guide.install.body": "把 HoneyMoney 加到主畫面——離線也能用，無需應用程式商店。Android 上開啟 ☰ 選單 →「安裝應用程式」即可一鍵安裝。iPhone / iPad 上，Apple 只允許透過 Safari 安裝：",
  "guide.ai.title": "AI——它做什麼（和不做什麼）",
  "guide.ai.intro": "AI 是選用的。這個應用程式不填任何密鑰也能以 RM 0 執行——收據掃描在你的裝置上完成。開啟 AI 後，記帳會變成一個基於你自己資金圖譜推理的助手，而不是一個通用聊天機器人：它永遠只是提議，由你確認，在你點頭之前什麼都不會儲存。",
  "guide.ai.1.label": "結合你的歷史來讀一張收據",
  "guide.ai.1.body": "轉發一張照片或電子錢包截圖——Honey 會讀出金額、商家和日期，歸入你平時給這家商戶用的分類，標出可能重複的記錄（「同一張收據兩人都發了」這個陷阱），並注意到訂閱或對你而言不尋常的金額——衡量的標準是你自己的過往，而不是陌生人的平均值。",
  "guide.ai.2.label": "著眼往前，從不訓人",
  "guide.ai.2.body": "Honey 的洞察看的是這個月正走向哪裡——例如「照這個速度，你的儲蓄目標會晚約六週」——並給出一個你可以採納也可以忽略的再平衡建議。它談的是計畫，不是你的個人消費，也絕不會逐條列出第三個分類。",
  "guide.ai.3.label": "離線可用，不花錢",
  "guide.ai.3.body": "收據掃描在你的裝置上執行，不消耗任何 token。只有當你想要更聰明、結合圖譜的解讀時，才需要加一個免費密鑰（Groq · Gemini · Ollama）。",
  "guide.ai.4.label": "主導權在你",
  "guide.ai.4.body": "AI 提議；你確認或更正。被儲存下來的是你的更正，而每一次改動都會寫入防竄改的稽核軌跡。",
  "guide.ai.setupLink": "去設定 →",
  "guide.ai.note": "Honey 屬於教育用途，不是財務建議——請見下方免責聲明。",
